package fixtures;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.Material;
import org.bukkit.plugin.java.JavaPlugin;
public final class EventsPlugin extends JavaPlugin implements Listener {
 private String mode="";
 @Override public boolean onCommand(org.bukkit.command.CommandSender sender,org.bukkit.command.Command command,String label,String[] args){
  if(args.length==0)return true;mode=args[0];
  if(mode.equals("permissions")){if(!sender.hasPermission("fixture.public.child")||sender.hasPermission("fixture.bypass"))throw new IllegalStateException("Права не соответствуют plugin.yml");sender.sendMessage("Permission inheritance verified; op="+sender.isOp());}
  if(mode.equals("world")&&sender instanceof org.bukkit.entity.Player){org.bukkit.entity.Player player=(org.bukkit.entity.Player)sender;org.bukkit.World world=player.getWorld();if(world.getEnvironment()!=org.bukkit.World.Environment.NORMAL||world.getMinHeight()!=-64||world.getMaxHeight()!=320||!world.getPlayers().contains(player)||world.getType(2,63,0)!=Material.STONE||world.getBlockAt(1,63,0).getRelative(1,0,0).getType()!=Material.STONE)throw new IllegalStateException("Неверный снимок мира");sender.sendMessage("World snapshot verified");}
  if(mode.equals("state")&&sender instanceof org.bukkit.entity.Player){
   org.bukkit.entity.Player p=(org.bukkit.entity.Player)sender;org.bukkit.World w=p.getWorld();
   if(!p.isValid()||p.getType()!=org.bukkit.entity.EntityType.PLAYER||p.getEyeHeight()<0.5||!Double.isFinite(p.getVelocity().getX())||p.isDead()||!p.canSee(p))throw new IllegalStateException("Неверное состояние игрока");
   p.getActivePotionEffects();p.getActiveItem();p.isOnGround();p.isInWater();p.isInLava();p.isInRain();p.isSneaking();p.getEyeLocation();p.setFireTicks(0);if(p.getFireTicks()!=0)throw new IllegalStateException("Огонь не изменился");p.giveExp(5);
   org.bukkit.inventory.ItemStack potion=new org.bukkit.inventory.ItemStack(Material.POTION);org.bukkit.inventory.meta.PotionMeta meta=(org.bukkit.inventory.meta.PotionMeta)potion.getItemMeta();meta.setBasePotionType(org.bukkit.potion.PotionType.LONG_POISON);potion.setItemMeta(meta);
   org.bukkit.entity.Item dropped=w.dropItem(p.getLocation().clone().add(0,4,0),potion);if(!dropped.isValid()||((org.bukkit.inventory.meta.PotionMeta)dropped.getItemStack().getItemMeta()).getBasePotionType()!=org.bukkit.potion.PotionType.LONG_POISON)throw new IllegalStateException("Зелье не передано миру");
   dropped.setVelocity(new org.bukkit.util.Vector(0,0,0));if(dropped.getVelocity().length()!=0)throw new IllegalStateException("Скорость не изменилась");dropped.setItemStack(new org.bukkit.inventory.ItemStack(Material.DIAMOND,2));if(dropped.getItemStack().getAmount()!=2)throw new IllegalStateException("Предмет не изменился");dropped.remove();if(dropped.isValid())throw new IllegalStateException("Предмет не удалён");
   org.bukkit.block.Block block=w.getBlockAt(2,63,0);org.bukkit.block.BlockState before=block.getState();block.setType(Material.DIRT);if(!before.update(true,false)||block.getType()!=Material.STONE)throw new IllegalStateException("Состояние блока не восстановлено");block.getLightLevel();block.getLightFromSky();block.isLiquid();block.isPassable();block.randomTick();if(!w.isChunkLoaded(0,0)||w.getHighestBlockYAt(block.getLocation())<63||w.getGameRuleValue(org.bukkit.GameRule.RANDOM_TICK_SPEED)<0)throw new IllegalStateException("Неверные сведения о мире");
   w.spawnParticle(org.bukkit.Particle.HEART,p.getLocation(),2,0.1,0.1,0.1);w.playSound(p.getLocation(),org.bukkit.Sound.BLOCK_ANVIL_USE,1,1);sender.sendMessage("Live state, potion, entity and block APIs verified");
  }
  if(mode.equals("native")&&sender instanceof org.bukkit.entity.Player){org.bukkit.entity.Player player=(org.bukkit.entity.Player)sender;org.bukkit.World world=player.getWorld();
   player.setAllowFlight(true);player.setFlying(true);player.setFlyingFallDamage(net.kyori.adventure.util.TriState.TRUE);if(!player.getAllowFlight()||!player.isFlying()||player.hasFlyingFallDamage()!=net.kyori.adventure.util.TriState.TRUE)throw new IllegalStateException("Снимок полёта потерян");player.setFlying(false);player.setAllowFlight(false);player.setFlyingFallDamage(net.kyori.adventure.util.TriState.NOT_SET);
   int limit=world.getSpawnLimit(org.bukkit.entity.SpawnCategory.MONSTER);world.setSpawnLimit(org.bukkit.entity.SpawnCategory.MONSTER,0);if(world.getSpawnLimit(org.bukkit.entity.SpawnCategory.MONSTER)!=0)throw new IllegalStateException("Предел спавна потерян");world.setSpawnLimit(org.bukkit.entity.SpawnCategory.MONSTER,limit);
   org.bukkit.Location at=player.getLocation();org.bukkit.util.RayTraceResult hit=world.rayTrace(at.clone().add(0,5,0),new org.bukkit.util.Vector(0,-1,0),8,org.bukkit.FluidCollisionMode.NEVER,true,0,e->e.equals(player));if(hit==null||!player.equals(hit.getHitEntity()))throw new IllegalStateException("Луч не нашёл игрока");
   org.bukkit.entity.Vex vex=world.spawn(at.clone().add(2,2,0),org.bukkit.entity.Vex.class,m->{m.setLimitedLifetime(true);m.setLimitedLifetimeTicks(40);m.setPersistent(false);m.setTarget(player);});if(!vex.isValid()||!player.equals(vex.getTarget())||!world.getEntitiesByClass(org.bukkit.entity.Vex.class).contains(vex))throw new IllegalStateException("Сущность не опубликована");vex.setHealth(5);vex.getEquipment().getItem(org.bukkit.inventory.EquipmentSlot.HAND);vex.teleport(at.clone().add(3,2,0));vex.remove();
   org.bukkit.entity.Fireball fire=player.launchProjectile(org.bukkit.entity.Fireball.class,new org.bukkit.util.Vector(0,1,0));fire.setYield(0);fire.setIsIncendiary(false);if(!player.equals(fire.getShooter()))throw new IllegalStateException("Потерян стрелок");fire.remove();
   org.bukkit.entity.ThrownPotion potion=player.launchProjectile(org.bukkit.entity.ThrownPotion.class,new org.bukkit.util.Vector(0,1,0));org.bukkit.inventory.ItemStack bottle=new org.bukkit.inventory.ItemStack(Material.SPLASH_POTION);org.bukkit.inventory.meta.PotionMeta meta=(org.bukkit.inventory.meta.PotionMeta)bottle.getItemMeta();meta.setBasePotionType(org.bukkit.potion.PotionType.HEALING);bottle.setItemMeta(meta);potion.setItem(bottle);if(potion.getEffects().isEmpty())throw new IllegalStateException("Эффект снаряда потерян");potion.remove();player.launchProjectile(org.bukkit.entity.WindCharge.class,new org.bukkit.util.Vector(0,1,0)).remove();
   org.bukkit.inventory.ItemStack book=new org.bukkit.inventory.ItemStack(Material.BOOK);org.bukkit.inventory.ItemStack enchanted=org.bukkit.Bukkit.getItemFactory().enchantWithLevels(book,30,false,new java.util.Random(12));if(enchanted.getType()!=Material.ENCHANTED_BOOK||book.getType()!=Material.BOOK||((org.bukkit.inventory.meta.EnchantmentStorageMeta)enchanted.getItemMeta()).getStoredEnchants().isEmpty())throw new IllegalStateException("Зачарование книги потеряно");
   sender.sendMessage("Native flight, rays, mobs, projectiles and enchantment verified");
  }
  if(mode.equals("consume")&&sender instanceof org.bukkit.entity.Player)((org.bukkit.entity.Player)sender).getInventory().setItem(2,new org.bukkit.inventory.ItemStack(Material.HONEY_BOTTLE));
  if(mode.equals("armor")&&sender instanceof org.bukkit.entity.Player)((org.bukkit.entity.Player)sender).getInventory().setItem(39,new org.bukkit.inventory.ItemStack(Material.DIAMOND_HELMET));
  sender.sendMessage("Event probe armed: "+mode);return true;
 }
 @EventHandler public void hunger(org.bukkit.event.entity.FoodLevelChangeEvent event){if(mode.equals("foodprotect")&&event.getFoodLevel()<((org.bukkit.entity.Player)event.getEntity()).getFoodLevel()){if(event.getItem()!=null)throw new IllegalStateException("У голода не должно быть предмета");event.setFoodLevel(((org.bukkit.entity.Player)event.getEntity()).getFoodLevel());((org.bukkit.entity.Player)event.getEntity()).sendMessage("Hunger event changed before food loss");}}
 @EventHandler public void entity(org.bukkit.event.player.PlayerInteractEntityEvent event){if(mode.equals("entityinteract")){if(!(event.getRightClicked() instanceof org.bukkit.entity.AbstractHorse))throw new IllegalStateException("Не получена лошадь");event.setCancelled(true);event.getPlayer().sendMessage("Entity interaction cancelled: "+event.getRightClicked().getType());}}
 @EventHandler public void craft(org.bukkit.event.inventory.PrepareItemCraftEvent event){if(mode.equals("craftbonus")&&event.getInventory().getResult()!=null&&event.getInventory().getResult().getType()==Material.BOOK){org.bukkit.inventory.ItemStack result=event.getInventory().getResult();result.setAmount(2);event.getInventory().setResult(result);event.getView().getPlayer().getUniqueId();}}
 @EventHandler public void source(org.bukkit.event.entity.EntityDamageByEntityEvent e){if(!mode.equals("source"))return;if(!(e.getDamager() instanceof org.bukkit.entity.Player)||!e.getDamager().getUniqueId().equals(e.getEntity().getUniqueId()))throw new IllegalStateException("Потерян прямой виновник урона");mode="";e.setDamage(0.5);((org.bukkit.entity.Player)e.getEntity()).sendMessage("Player damage source delivered and changed to 0.5");}
 @EventHandler public void swap(PlayerSwapHandItemsEvent e){if(mode.equals("swap")){mode="";e.setCancelled(true);e.getPlayer().sendMessage("Hand swap cancelled before inventory mutation");}}
 @EventHandler public void held(PlayerItemHeldEvent e){if(mode.equals("held")){mode="";e.setCancelled(true);e.getPlayer().sendMessage("Held slot cancelled before selection");}}
 @EventHandler public void consume(PlayerItemConsumeEvent e){if(mode.equals("consume")){mode="";if(e.getItem().getType()!=Material.HONEY_BOTTLE)throw new IllegalStateException("Неверная еда");e.setCancelled(true);e.getPlayer().sendMessage("Consume cancelled before effects and item removal");}}
 @EventHandler public void move(PlayerMoveEvent event){if(!mode.equals("move")||!event.hasChangedPosition())return;mode="";event.setCancelled(true);event.getPlayer().sendMessage("Movement cancelled before physics");}
 @EventHandler public void jump(com.destroystokyo.paper.event.player.PlayerJumpEvent event){if(!mode.equals("jump"))return;mode="";event.setCancelled(true);event.getPlayer().sendMessage("Jump cancelled before physics");}
 @EventHandler public void interact(PlayerInteractEvent event){if(mode.equals("trace"))event.getPlayer().sendMessage("Interaction trace: "+event.getAction()+" cancelled="+event.isCancelled()+" at="+event.getPlayer().getLocation().getX()+","+event.getPlayer().getLocation().getY()+","+event.getPlayer().getLocation().getZ()+" mode="+event.getPlayer().getGameMode());if(!mode.equals("interact"))return;mode="";event.setCancelled(true);event.getPlayer().sendMessage("Interaction cancelled; hand="+event.getHand());}
 @EventHandler public void armor(com.destroystokyo.paper.event.player.PlayerArmorChangeEvent event){if(mode.equals("armor")&&event.getNewItem().getType()==Material.DIAMOND_HELMET){mode="";event.getPlayer().sendMessage("Armor change delivered: "+event.getSlot());}}
 @EventHandler public void respawn(PlayerRespawnEvent event){event.getPlayer().sendMessage("Respawn delivered; bed="+event.isBedSpawn()+"; anchor="+event.isAnchorSpawn());}
 @EventHandler public void modernChat(io.papermc.paper.event.player.AsyncChatEvent event){if(event.message() instanceof net.kyori.adventure.text.TextComponent&&((net.kyori.adventure.text.TextComponent)event.message()).content().equals("render-java"))event.renderer((source,name,message,viewer)->net.kyori.adventure.text.Component.text("Rendered chat: ").append(message));}
 @EventHandler public void bed(PlayerBedEnterEvent event){if(!mode.equals("bed"))return;mode="";if(event.enterAction().problem()!=null||!event.enterAction().canSetSpawn().success())throw new IllegalStateException("Кровать не прошла правила");event.setCancelled(true);event.getPlayer().setRespawnLocation(event.getBed().getLocation());event.getPlayer().sendMessage("Bed cancelled with real spawn rules");}
 @Override public void onLoad(){getLogger().info("Event fixture metadata initialized");}
 @Override public void onEnable(){getLogger().info("Event fixture registering listeners");getServer().getPluginManager().registerEvents(this,this);}
 @EventHandler public void join(PlayerJoinEvent event){event.getPlayer().sendMessage("Вход из Java работает");}
 @EventHandler public void chat(AsyncPlayerChatEvent event){if(event.getMessage().equals("cancel-java")){event.setCancelled(true);event.getPlayer().sendMessage("Отмена чата из Java работает");}}
 @EventHandler public void block(BlockBreakEvent event){event.setCancelled(true);event.getPlayer().sendMessage("Отмена блока из Java работает");}
 @EventHandler public void place(BlockPlaceEvent event){if(event.getBlockPlaced().getType()==Material.STONE){event.setCancelled(true);event.getPlayer().sendMessage("Отмена установки из Java работает");}}
 @EventHandler public void command(PlayerCommandPreprocessEvent event){if(event.getMessage().equals("/java-blocked")){event.setCancelled(true);event.getPlayer().sendMessage("Отмена команды из Java работает");}}
 @EventHandler public void damage(org.bukkit.event.entity.EntityDamageEvent event){
  if(event.getCause()==org.bukkit.event.entity.EntityDamageEvent.DamageCause.CUSTOM){event.setDamage(1);((org.bukkit.entity.Player)event.getEntity()).sendMessage("Урон из Java изменён на 1");}
  if(event.getCause()==org.bukkit.event.entity.EntityDamageEvent.DamageCause.FALL){event.setCancelled(true);((org.bukkit.entity.Player)event.getEntity()).sendMessage("Урон от падения из Java отменён");}
 }
 @EventHandler public void death(org.bukkit.event.entity.PlayerDeathEvent event){event.getEntity().sendMessage("Смерть из Java работает");}
}
